// real, src/inbox.ts
markRead(userId: string, itemId: string): MarkResult {
  const entry = this.boxes.get(userId)?.byId.get(itemId); // only THIS user's items
  if (!entry) return "not_found";
  if (entry.readAt !== undefined) return "already_read";
  entry.readAt = this.clock.now();
  this.boxes.get(userId)!.unread--;
  return "marked";
}

// solution (exercise; not in the repo) -- src/inbox.ts, inside InMemoryInbox
markUnread(userId: string, itemId: string): "marked" | "already_unread" | "not_found" {
  const box = this.boxes.get(userId);
  const entry = box?.byId.get(itemId);
  if (!box || !entry) return "not_found";
  if (entry.readAt === undefined) return "already_unread"; // no state change -> no counter change
  delete entry.readAt;
  box.unread++;
  return "marked";
}

