it("a stalled worker removes a dead token at once, but its device log is dropped", async () => {
  const { notifier, worker, push, users, clock } = setupQueued({ users: [{ ...FULL_USER, pushTokens: ["tok-a", "tok-b"] }] });
  const lateA = gate<SendResult>();
  const lateB = gate<SendResult>();
  push.willAnswer(
    () => lateA.promise, // stalled worker, tok-a
    () => lateB.promise, // stalled worker, tok-b
    failed(true, "503"), // new owner, tok-a; tok-b then gets the default "sent"
  );
  const r = notifier.notify(orderReq());
  const jobs = notifier.claim(4);
  const stalled = Promise.all(jobs.map((j) => notifier.process(j)));
  clock.advance(30_000); // the stalled worker's leases run out
  await worker.drain(); // the new owner sends
  const before = notifier.get(r.id)!.deliveries[0]!;
  expect(before.status).toBe("sent");

  lateA.resolve(dead); // permanent + invalidAddress
  lateB.resolve(failed(true, "late"));
  await stalled;

  expect(users.get("u1")!.pushTokens).toEqual(["tok-b"]); // removed, though the lease was lost
  const d = notifier.get(r.id)!.deliveries[0]!;
  expect(d.devices!.map((x) => `${x.token}:${x.status}`)).toEqual(["tok-a:failed", "tok-b:sent"]); // the new owner's log
  expect(d.devices![0]).not.toHaveProperty("removed");
  expect(notifier.stats.leaseLost).toBeGreaterThanOrEqual(1);
});
